import ast
from abc import ABC, abstractmethod
from typing import Union

from numpy.typing import NDArray
from tokencost import count_message_tokens, count_string_tokens

from routers.common import TOKEN_COSTS


def get_prompt_token_cost(tokencost_model_name: str) -> float:
    return TOKEN_COSTS[tokencost_model_name]["prompt"]


def get_model_request_cost(tokencost_model_name: str) -> float:
    try:
        return TOKEN_COSTS[tokencost_model_name]["request"]
    except KeyError:
        return 0.0


def get_completion_token_cost(tokencost_model_name: str) -> float:
    return TOKEN_COSTS[tokencost_model_name]["completion"]


def get_tokens_for_response(response: Union[str, list[str]], tokencost_model_name) -> int:
    if isinstance(response, str):
        if response[0] == "[" and response[-1] == "]":
            response = str(ast.literal_eval(response))
    elif not isinstance(response, list):
        response = str(response)  # want responses to be strings
    try:
        return count_string_tokens(response, tokencost_model_name)
    except ValueError:
        try:
            return count_message_tokens(response, tokencost_model_name)
        except ValueError:
            return 0


def calculate_cost_for_prompt_and_response(
    prompt: Union[str, list[str]], response: Union[str, list[str]], model_name: str
) -> float:
    """
    Calculate the cost in USD for a prompt given a model name

    :param prompt: The prompt to calculate the cost for
    :param model_name: The name of the model to calculate the cost for
    :return: The cost of the prompt
    """
    model_name_map = {
        'claude-instant-v1': 'anthropic.claude-instant-v1',
        'claude-v1': 'anthropic.claude-v1',
        'claude-v2': 'anthropic.claude-v2',
        'meta/llama-2-70b-chat': 'replicate/meta/llama-2-70b-chat',
        'mistralai/mixtral-8x7b-chat': 'mistral/open-mixtral-8x7b',
        'zero-one-ai/Yi-34B-Chat': 'deepinfra/01-ai/Yi-34B-Chat',
        'WizardLM/WizardLM-13B-V1.2': 'openrouter/gryphe/mythomax-l2-13b',
        'meta/code-llama-instruct-34b-chat': 'replicate/meta/codellama-34b-instruct',
        'mistralai/mistral-7b-chat': 'mistral/mistral-7b-instruct-v0.2',
        'openai-gpt-3.5-turbo-0301': 'gpt-3.5-turbo-1106',
        'openai-gpt-3.5-turbo-0613': 'gpt-3.5-turbo-1106',
        'openai-gpt-3.5-turbo-1106': 'gpt-3.5-turbo-1106',
        'openai-gpt-3.5-turbo-instruct': 'gpt-3.5-turbo-1106',
        'openai-gpt-4-0314': 'gpt-4-1106-preview',
        'openai-gpt-4-0613': 'gpt-4-1106-preview',
        'openai-gpt-4-1106-preview': 'gpt-4-1106-preview',
        'openai-gpt-4-base': 'gpt-4-1106-preview',
        'openai-gpt-4-turbo-preview': 'gpt-4-1106-preview',
        'anthropic-claude-instant-1': 'claude-instant-v1',
        'anthropic-claude-2.0': 'claude-v2',
        'anthropic-claude-2.1': 'claude-v2',
        'google-gemini-pro': 'google-gemini-pro',
        'google-gemini-pro-vision': 'google-gemini-pro-vision',
        'cohere-command-nightly': 'cohere-command-nightly',
        'meta-llama-llama-2-70b-chat': 'meta/llama-2-70b-chat',
        'mistral-ai-mistral-7b-instruct': 'mistralai/mistral-7b-chat',
        'mistral-ai-mixtral-8x7b-instruct': 'mistralai/mixtral-8x7b-chat',
    }
    tokencost_model_name = model_name_map.get(model_name, model_name)

    if isinstance(prompt, str):
        if prompt[0] == "[" and prompt[-1] == "]":
            prompt = ast.literal_eval(prompt)
    elif not isinstance(prompt, list):
        prompt = str(prompt)
    if isinstance(response, str):
        if response[0] == "[" and response[-1] == "]":
            response = ast.literal_eval(response)
    elif not isinstance(response, list):
        response = str(response)  # want responses to be strings
    if isinstance(prompt, list):
        prompt_cost = sum(
            [count_string_tokens(p, tokencost_model_name) for p in prompt]
        ) * get_prompt_token_cost(tokencost_model_name)
        response_cost = sum(
            [count_string_tokens(r, tokencost_model_name) for r in response]
        ) * get_completion_token_cost(tokencost_model_name)
        cost = prompt_cost + response_cost + get_model_request_cost(tokencost_model_name)
        print(f"List prompt_cost: {prompt_cost}, response_cost: {response_cost}, cost: {cost}")
    else:
        if isinstance(response, str):
            prompt_cost = count_string_tokens(
                prompt, tokencost_model_name
            ) * get_prompt_token_cost(tokencost_model_name)
            response_cost = count_string_tokens(
                response, tokencost_model_name
            ) * get_completion_token_cost(tokencost_model_name)
        else:
            tokens = count_string_tokens(prompt, tokencost_model_name)
            prompt_cost = tokens * get_prompt_token_cost(tokencost_model_name)
            response_cost = 0.0
        cost = prompt_cost + response_cost + get_model_request_cost(tokencost_model_name)
        print(f"String prompt_cost: {prompt_cost}, response_cost: {response_cost}, cost: {cost}")
    return cost


class AbstractRouter(ABC):
    @abstractmethod
    def __init__(self, **kwargs) -> None:
        """
        Initialize the routing algorithm, fit the model or load data weights, etc.
        """
        pass

    @abstractmethod
    def batch_route_prompts(self, prompts: list[str], **kwargs) -> NDArray[str]:
        """
        :param prompts: List of prompts to route to.
        :param kwargs: for example, willingness_to_pay
        :return: should return an array of model names (str) in MODELS_TO_ROUTE
        """
        pass

